{
  "approach": "Begin with a controlled log-only inspection phase. All initial workers observe and categorize incidents without applying fixes. After establishing a baseline of correct identifications, selectively grant config/contract access to workers whose specialties match incident families. Enforce the three mandatory criteria at every step: sealed_pass_rate must reach 1.0, regressions must remain at 0, and work_units should be minimized after correctness is confirmed.",
  "success_criteria": [
    "sealed_pass_rate reaches 1.0",
    "regressions remain at 0",
    "work_units minimized after full correctness"
  ],
  "initial_specialties": [
    "routing"
  ]
}

{
  "observation": {
    "weakness": "Routing config has mismatched health_path and port values across incidents. Development evidence shows health_path set to /old/... or /old/b66134b1 while contract requires /ready/... and listening_port is 5000 but config has 8000/8080. This causes probe_reaches_route and probe_reaches_listener failures.",
    "lesson": "Routing family requires health_path and port to exactly match registered_health_path and listening_port from contract. Current workflow applies rules after log reading but rules likely ignore contract constraints."
  },
  "mutations": [
    {
      "name": "routing_fix",
      "reason": "Align routing config with contract to satisfy probe checks and reduce work_units.",
      "changes": {
        "agents": [
          {
            "id": "routing",
            "specialty": "routing",
            "tools": ["read_logs", "inspect_config", "inspect_contract"],
            "instructions": "Diagnose routing symptoms from log evidence and verify health_path/port against contract before applying rules."
          }
        ],
        "workflow": [
          {
            "agent": "routing",
            "action": "read_logs"
          },
          {
            "agent": "routing",
            "action": "inspect_contract"
          },
          {
            "agent": "routing",
            "action": "inspect_config"
          },
          {
            "agent": "routing",
            "action": "apply_rules"
          },
          {
            "agent": "controller",
            "action": "commit"
          }
        ],
        "review_policy": "schema",
        "memory_policy": "none",
        "cache_evidence": false
      }
    },
    {
      "name": "capacity_optimize",
      "reason": "Capacity incidents show pool_size exceeds connection_budget or workers misconfigured. Optimizing pool_size to fit within budget reduces retries and latency amplification.",
      "changes": {
        "agents": [
          {
            "id": "capacity",
